-- =============================================================================
-- 1200 · Casos de prueba por vertical (restaurante, veterinaria, aerolínea)
-- El profesor elige un caso en el panel: se crea el negocio con su catálogo (5 ítems con imagen)
-- y, desde el panel, llegan 20 mensajes de prueba con las respuestas de Eli.
-- =============================================================================

create or replace function elius.datos_caso_demo(p_vertical text)
returns jsonb language sql immutable set search_path = '' as $$
  select case p_vertical
    when 'restaurante' then '{"negocio": "Restaurante Sabor Criollo", "categorias": ["Platos fuertes", "Bebidas", "Postres"], "contactos": [["Camila", "Rojas", "+573001110001"], ["Andrés", "Pardo", "+573001110002"], ["Laura", "Gómez", "+573001110003"], ["Felipe", "Martínez", "+573001110004"], ["Valentina", "Ortiz", "+573001110005"], ["Daniel", "Herrera", "+573001110006"], ["Sofía", "Vargas", "+573001110007"], ["Juan", "Castillo", "+573001110008"], ["Mariana", "Suárez", "+573001110009"], ["Camilo", "Reyes", "+573001110010"], ["Natalia", "Moreno", "+573001110011"], ["Esteban", "Cárdenas", "+573001110012"], ["Paula", "Jiménez", "+573001110013"], ["Sebastián", "Ruiz", "+573001110014"], ["Isabela", "Pineda", "+573001110015"], ["Tomás", "Aguirre", "+573001110016"], ["Gabriela", "Salazar", "+573001110017"], ["Mateo", "Duarte", "+573001110018"], ["Alejandra", "Rincón", "+573001110019"], ["Nicolás", "Quintero", "+573001110020"]], "items": [{"cat": 0, "tipo": "producto", "sku": "RES-01", "nombre": "Bandeja paisa", "desc": "Frijoles, arroz, carne molida, chicharrón, chorizo, huevo, plátano maduro y arepa.", "precio": 38000, "iva": 8, "dur": null}, {"cat": 0, "tipo": "producto", "sku": "RES-02", "nombre": "Hamburguesa de la casa", "desc": "Carne de res 180 g, queso, tocineta y papas a la francesa.", "precio": 28000, "iva": 8, "dur": null}, {"cat": 0, "tipo": "producto", "sku": "RES-03", "nombre": "Arepa rellena de pollo", "desc": "Arepa de maíz rellena de pollo desmechado con guacamole.", "precio": 16000, "iva": 8, "dur": null}, {"cat": 1, "tipo": "producto", "sku": "RES-04", "nombre": "Limonada de coco", "desc": "Limonada cremada con coco, servida bien fría.", "precio": 12000, "iva": 8, "dur": null}, {"cat": 2, "tipo": "producto", "sku": "RES-05", "nombre": "Tres leches", "desc": "Bizcocho bañado en tres leches con crema y canela.", "precio": 14000, "iva": 8, "dur": null}], "guion": [{"conv": 0, "emisor": "cliente", "texto": "Hola, buenas noches. ¿Tienen mesa para 4 personas mañana a las 8 pm?", "img": null}, {"conv": 0, "emisor": "eli", "texto": "¡Hola Camila! Bienvenida a Sabor Criollo 🍽️ Mañana a las 8:00 p. m. tenemos mesa para 4 en la terraza. ¿Te la reservo a tu nombre?", "img": null}, {"conv": 1, "emisor": "cliente", "texto": "Buenas, quiero pedir a domicilio una bandeja paisa", "img": null}, {"conv": 1, "emisor": "eli", "texto": "¡Hola Andrés! Esta es nuestra Bandeja paisa ($38.000): frijoles, arroz, carne molida, chicharrón, chorizo, huevo, plátano y arepa. ¿A qué dirección la enviamos?", "img": 1}, {"conv": 2, "emisor": "cliente", "texto": "Hola, ¿ustedes tienen opciones sin gluten?", "img": null}, {"conv": 2, "emisor": "eli", "texto": "Hola Laura 😊 La Arepa rellena de pollo ($16.000) es de maíz y no lleva gluten. Si tu alergia es severa te paso con el administrador para confirmar con cocina.", "img": 3}, {"conv": 3, "emisor": "cliente", "texto": "¿Cuánto vale la hamburguesa?", "img": null}, {"conv": 3, "emisor": "eli", "texto": "Hola Felipe, la Hamburguesa de la casa cuesta $28.000: carne de res de 180 g, queso, tocineta y papas a la francesa.", "img": 2}, {"conv": 4, "emisor": "cliente", "texto": "Quiero algo fresco para tomar, ¿qué me recomiendas?", "img": null}, {"conv": 4, "emisor": "eli", "texto": "¡Hola Valentina! Te recomiendo la Limonada de coco ($12.000), cremada y bien fría 🥥", "img": 4}, {"conv": 5, "emisor": "cliente", "texto": "¿Tienen postres? Es para un cumpleaños", "img": null}, {"conv": 5, "emisor": "eli", "texto": "¡Claro, Daniel! 🎂 Nuestro Tres leches ($14.000) es el favorito para celebrar; podemos llevarlo con una vela.", "img": 5}, {"conv": 6, "emisor": "cliente", "texto": "Hola, ¿a qué hora abren hoy?", "img": null}, {"conv": 6, "emisor": "eli", "texto": "Hola Sofía, hoy atendemos de 12:00 m. a 10:00 p. m. ¿Quieres que te reserve una mesa?", "img": null}, {"conv": 7, "emisor": "cliente", "texto": "Necesito reservar para 12 personas el sábado", "img": null}, {"conv": 7, "emisor": "eli", "texto": "Hola Juan, para grupos grandes aviso de inmediato al administrador para organizar la mesa. ¿Me confirmas la hora y un teléfono de contacto?", "img": null}, {"conv": 8, "emisor": "cliente", "texto": "Me gustaría pedir 2 arepas rellenas y una limonada", "img": null}, {"conv": 8, "emisor": "eli", "texto": "¡Perfecto, Mariana! 2 Arepas rellenas ($32.000) y 1 Limonada de coco ($12.000): total $44.000. ¿Domicilio o recoges en el local?", "img": 3}, {"conv": 9, "emisor": "cliente", "texto": "¿Hacen domicilios a Chapinero?", "img": null}, {"conv": 9, "emisor": "eli", "texto": "Sí, Camilo, llegamos a Chapinero. El domicilio vale $5.000 y tarda unos 40 minutos. ¿Qué te provoca pedir?", "img": null}, {"conv": 10, "emisor": "cliente", "texto": "¿La bandeja paisa alcanza para dos?", "img": null}, {"conv": 10, "emisor": "eli", "texto": "Hola Natalia, la Bandeja paisa es generosa y para dos personas puede alcanzar si piden entradas. Aquí te la muestro 😊", "img": 1}, {"conv": 11, "emisor": "cliente", "texto": "Quiero cancelar mi reserva de mañana", "img": null}, {"conv": 11, "emisor": "eli", "texto": "Listo Esteban, ¿me confirmas a nombre de quién estaba? Cancelo la reserva y te aviso. La consignación se puede reagendar según disponibilidad.", "img": null}, {"conv": 12, "emisor": "cliente", "texto": "Ya consigné los $20.000 de la reserva", "img": null}, {"conv": 12, "emisor": "eli", "texto": "Gracias Paula 🙌 Envíame la foto del comprobante y una persona del restaurante verifica que el monto haya llegado para confirmarte.", "img": null}, {"conv": 13, "emisor": "cliente", "texto": "📎 Comprobante de consignación $20.000.jpg", "img": null}, {"conv": 13, "emisor": "eli", "texto": "Recibido, Sebastián. Lo estamos validando; cuando el administrador confirme el monto, tu reserva queda confirmada ✅", "img": null}, {"conv": 14, "emisor": "cliente", "texto": "¿Tienen menú para niños?", "img": null}, {"conv": 14, "emisor": "eli", "texto": "Hola Isabela, tenemos porciones pequeñas: la Hamburguesa de la casa en tamaño infantil. Aquí está la versión normal para que la veas.", "img": 2}, {"conv": 15, "emisor": "cliente", "texto": "Quiero la bandeja paisa y un tres leches", "img": null}, {"conv": 15, "emisor": "eli", "texto": "¡Buena elección, Tomás! 1 Bandeja paisa ($38.000) + 1 Tres leches ($14.000) = $52.000. ¿Lo enviamos a domicilio?", "img": 5}, {"conv": 16, "emisor": "cliente", "texto": "¿Aceptan pago con Nequi?", "img": null}, {"conv": 16, "emisor": "eli", "texto": "Sí, Gabriela: aceptamos Nequi, Bre-B y transferencia. Envíanos el comprobante y confirmamos tu pedido.", "img": null}, {"conv": 17, "emisor": "cliente", "texto": "¿Se puede reservar en la terraza?", "img": null}, {"conv": 17, "emisor": "eli", "texto": "Claro, Mateo 🌿 La terraza tiene cupo mañana a las 7:00 y 8:30 p. m. ¿Para cuántas personas?", "img": null}, {"conv": 18, "emisor": "cliente", "texto": "Mi pedido no ha llegado, llevo una hora esperando", "img": null}, {"conv": 18, "emisor": "eli", "texto": "Lamento la demora, Alejandra. Ya aviso al administrador para que lo revise de inmediato y te escribe una persona del equipo en unos minutos.", "img": null}, {"conv": 19, "emisor": "cliente", "texto": "Gracias, todo estuvo delicioso 😍", "img": null}, {"conv": 19, "emisor": "eli", "texto": "¡Qué alegría, Nicolás! Gracias por visitarnos. Te esperamos pronto en Sabor Criollo 🍽️", "img": null}]}'::jsonb
    when 'veterinaria' then '{"negocio": "Clínica Veterinaria Huellitas", "categorias": ["Consultas y cirugía", "Prevención", "Estética"], "contactos": [["Mariana", "Ruiz", "+573002220001"], ["Julián", "Castro", "+573002220002"], ["Paola", "Díaz", "+573002220003"], ["Camilo", "Torres", "+573002220004"], ["Lucía", "Ramírez", "+573002220005"], ["Andrés", "Cifuentes", "+573002220006"], ["Diana", "Mejía", "+573002220007"], ["Santiago", "Londoño", "+573002220008"], ["Carolina", "Ospina", "+573002220009"], ["Mauricio", "Gil", "+573002220010"], ["Juliana", "Arango", "+573002220011"], ["Ricardo", "Bermúdez", "+573002220012"], ["Manuela", "Parra", "+573002220013"], ["Felipe", "Osorio", "+573002220014"], ["Angélica", "Mora", "+573002220015"], ["Jorge", "Villa", "+573002220016"], ["Natalia", "Cortés", "+573002220017"], ["Oscar", "Franco", "+573002220018"], ["Daniela", "Peña", "+573002220019"], ["Esteban", "Vega", "+573002220020"]], "items": [{"cat": 0, "tipo": "servicio", "sku": "VET-01", "nombre": "Consulta general", "desc": "Examen clínico completo con orientación de tratamiento.", "precio": 60000, "iva": 0, "dur": 30}, {"cat": 1, "tipo": "servicio", "sku": "VET-02", "nombre": "Vacuna múltiple", "desc": "Esquema anual para perros y gatos, con carné actualizado.", "precio": 75000, "iva": 0, "dur": 20}, {"cat": 2, "tipo": "servicio", "sku": "VET-03", "nombre": "Baño y peluquería", "desc": "Baño medicado, corte de pelo y de uñas, limpieza de oídos.", "precio": 55000, "iva": 19, "dur": 90}, {"cat": 1, "tipo": "servicio", "sku": "VET-04", "nombre": "Desparasitación", "desc": "Desparasitante interno y externo según el peso de la mascota.", "precio": 35000, "iva": 0, "dur": 15}, {"cat": 0, "tipo": "servicio", "sku": "VET-05", "nombre": "Esterilización canina", "desc": "Cirugía con anestesia, exámenes previos y control posoperatorio.", "precio": 320000, "iva": 0, "dur": 120}], "guion": [{"conv": 0, "emisor": "cliente", "texto": "Hola, mi perro Max tiene las vacunas atrasadas, ¿puedo