ll}, {"conv": 7, "emisor": "eli", "texto": "Perfecto, Santiago. La Desparasitación ($35.000 por mascota) se da según el peso. Para los dos serían $70.000. ¿Qué día te sirve?", "img": 4}, {"conv": 8, "emisor": "cliente", "texto": "¿Tienen servicio de peluquería para un schnauzer?", "img": null}, {"conv": 8, "emisor": "eli", "texto": "Claro, Carolina 🐾 El Baño y peluquería ($55.000) incluye corte de raza. Hay cupo mañana a las 9:00 a. m.", "img": 3}, {"conv": 9, "emisor": "cliente", "texto": "Mi perro cojea desde ayer", "img": null}, {"conv": 9, "emisor": "eli", "texto": "Hola Mauricio, conviene que lo vea el veterinario pronto. Te agendo una Consulta general ($60.000) hoy o mañana a primera hora. ¿Cuál prefieres?", "img": 1}, {"conv": 10, "emisor": "cliente", "texto": "¿A qué edad se esteriliza una gata?", "img": null}, {"conv": 10, "emisor": "eli", "texto": "Hola Juliana, normalmente desde los 6 meses, según su peso y salud. Lo ideal es una consulta para valorarla antes de agendar.", "img": null}, {"conv": 11, "emisor": "cliente", "texto": "Quiero cancelar la cita de hoy", "img": null}, {"conv": 11, "emisor": "eli", "texto": "Listo Ricardo, ¿me confirmas el nombre de la mascota? Cancelo la cita y te ofrezco otra fecha cuando quieras.", "img": null}, {"conv": 12, "emisor": "cliente", "texto": "Ya hice la consignación de la consulta", "img": null}, {"conv": 12, "emisor": "eli", "texto": "Gracias Manuela 🙌 Envíame la foto del comprobante y confirmamos tu cita apenas se verifique el monto.", "img": null}, {"conv": 13, "emisor": "cliente", "texto": "📎 Comprobante consignación $60.000.jpg", "img": null}, {"conv": 13, "emisor": "eli", "texto": "Recibido, Felipe. Lo estamos validando; cuando se confirme el monto tu cita queda confirmada ✅", "img": null}, {"conv": 14, "emisor": "cliente", "texto": "¿La vacuna múltiple sirve para gatos?", "img": null}, {"conv": 14, "emisor": "eli", "texto": "Hola Angélica, para gatos usamos la vacuna triple felina; la Vacuna múltiple ($75.000) cubre el esquema anual según la especie. Aquí te la muestro.", "img": 2}, {"conv": 15, "emisor": "cliente", "texto": "¿Tienen guardería para perros?", "img": null}, {"conv": 15, "emisor": "eli", "texto": "Hola Jorge, por ahora no ofrecemos guardería, pero sí consulta, vacunas, baño y cirugías. ¿Te ayudo con alguno?", "img": null}, {"conv": 16, "emisor": "cliente", "texto": "Mi cachorro tiene diarrea hace 2 días", "img": null}, {"conv": 16, "emisor": "eli", "texto": "Hola Natalia, en cachorros la diarrea puede deshidratar rápido. Te agendo una Consulta general ($60.000) hoy mismo y aviso al veterinario.", "img": 1}, {"conv": 17, "emisor": "cliente", "texto": "¿Cómo es el procedimiento de la esterilización?", "img": null}, {"conv": 17, "emisor": "eli", "texto": "Hola Óscar, se hace con anestesia y exámenes previos; la mascota sale el mismo día con indicaciones de cuidado. Te muestro el servicio.", "img": 5}, {"conv": 18, "emisor": "cliente", "texto": "¿Puedo llevar a mi mascota sin cita?", "img": null}, {"conv": 18, "emisor": "eli", "texto": "Hola Daniela, para urgencias sí; para consultas de rutina es mejor agendar y así no esperas. ¿Te busco un cupo?", "img": null}, {"conv": 19, "emisor": "cliente", "texto": "Gracias por atender tan rápido a Luna 🐱", "img": null}, {"conv": 19, "emisor": "eli", "texto": "¡Gracias a ti, Esteban! Nos alegra que Luna esté mejor. Cualquier duda, aquí estoy.", "img": null}]}'::jsonb
    when 'aerolinea' then '{"negocio": "Aerolínea Cóndor Andino", "categorias": ["Tarifas", "Servicios adicionales"], "contactos": [["Sergio", "Molina", "+573003330001"], ["Daniela", "Vargas", "+573003330002"], ["Carlos", "Núñez", "+573003330003"], ["Laura", "Cárdenas", "+573003330004"], ["Andrés", "Rojas", "+573003330005"], ["Paula", "Medina", "+573003330006"], ["Julián", "Pardo", "+573003330007"], ["Camila", "Soto", "+573003330008"], ["Felipe", "Gómez", "+573003330009"], ["Valeria", "Sánchez", "+573003330010"], ["Mateo", "Arias", "+573003330011"], ["Sara", "Londoño", "+573003330012"], ["Nicolás", "Ibarra", "+573003330013"], ["Isabella", "Rey", "+573003330014"], ["David", "Correa", "+573003330015"], ["Luisa", "Bernal", "+573003330016"], ["Diego", "Vásquez", "+573003330017"], ["Mónica", "Pacheco", "+573003330018"], ["Alejandro", "Ríos", "+573003330019"], ["Juliana", "Cano", "+573003330020"]], "items": [{"cat": 0, "tipo": "tarifa", "sku": "AER-01", "nombre": "Bogotá – Medellín (Light)", "desc": "Solo equipaje de mano. Sin cambios ni devolución.", "precio": 189000, "iva": 19, "dur": null}, {"cat": 0, "tipo": "tarifa", "sku": "AER-02", "nombre": "Bogotá – Cartagena (Flex)", "desc": "Maleta de 23 kg incluida y un cambio de fecha sin costo.", "precio": 329000, "iva": 19, "dur": null}, {"cat": 0, "tipo": "tarifa", "sku": "AER-03", "nombre": "Bogotá – San Andrés (Promo)", "desc": "Tarifa promocional con equipaje de mano, cupos limitados.", "precio": 415000, "iva": 19, "dur": null}, {"cat": 1, "tipo": "adicional", "sku": "AER-04", "nombre": "Maleta de bodega 23 kg", "desc": "Equipaje adicional para tu vuelo.", "precio": 85000, "iva": 19, "dur": null}, {"cat": 1, "tipo": "adicional", "sku": "AER-05", "nombre": "Selección de asiento", "desc": "Elige ventana o pasillo antes del check-in.", "precio": 25000, "iva": 19, "dur": null}], "guion": [{"conv": 0, "emisor": "cliente", "texto": "Hola, necesito un vuelo Bogotá–Medellín el viernes en la mañana", "img": null}, {"conv": 0, "e